const allRatings = await browserjs(tabId, () => {
  const feed = document.querySelector('[role="feed"]');
  const items = Array.from(feed.querySelectorAll('a[href*="/maps/place/"]')).map(a => {
    const card = a.closest('div[jsaction]') || a.parentElement;
    const text = card ? card.innerText : a.innerText;
    const match = text.match(/([0-5]\.[0-9])\(([0-9,]+)\)/);
    const title = a.getAttribute('aria-label') || text.split('\n')[0];
    const isSponsored = /sponsored/i.test(text);
    return {
      title,
      isSponsored,
      rating: match ? parseFloat(match[1]) : null,
      reviews: match ? parseInt(match[2].replace(/,/g, '')) : null,
      snippet: text.replace(/\n+/g, ' | ').slice(0, 150)
    };
  });
  return items;
});

