const tabId = 248688717;

const hotels = await browserjs(tabId, async () => {
  const feed = document.querySelector('[role="feed"]');
  if (!feed) return { error: "no feed" };

  // Helper to extract hotels currently in feed
  function getHotels() {
    const cards = Array.from(feed.querySelectorAll('div[jsaction]')).filter(el => {
      // Check if this looks like a hotel card
      return el.querySelector('a[href*="/maps/place/"]') || (el.innerText && el.innerText.includes('-star hotel'));
    });

    // Better yet, find all place links or headers
    const results = [];
    const placeLinks = Array.from(feed.querySelectorAll('a[href*="/maps/place/"]'));
    for (const a of placeLinks) {
      const container = a.closest('div[jsaction]') || a.parentElement;
      const text = container ? container.innerText : a.innerText;
      const href = a.href;
      const title = a.getAttribute('aria-label') || a.innerText.split('\n')[0];
      if (title && !results.some(r => r.title === title)) {
        results.push({ title, href, textSnippet: text.slice(0, 300) });
      }
    }
    return results;
  }

  // Scroll a few times to load top results
  for (let i = 0; i < 5; i++) {
    feed.scrollTop = feed.scrollHeight;
    await new Promise(r => setTimeout(r, 1000));
  }

  return getHotels();
});

console.log("Found hotels count:", hotels.length);
console.log(JSON.stringify(hotels.slice(0, 15), null, 2));

